package br.com.tapeteskalke.controller; import br.com.tapeteskalke.dto.ApiResponse; import br.com.tapeteskalke.service.*; import java.time.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/relatorios") public class RelatorioController { private final RelatorioService service; private final PermissionService permissions; private final Clock clock; public RelatorioController(RelatorioService service,PermissionService permissions,Clock clock){this.service=service;this.permissions=permissions;this.clock=clock;} @GetMapping("/financeiro") public ApiResponse<?> financeiro(@RequestParam(required=false)LocalDate inicio,@RequestParam(required=false)LocalDate fim){permissions.action("relatorios_visualizar");var today=LocalDate.now(clock);var start=inicio==null?today.withDayOfMonth(1):inicio;var end=fim==null?today:fim;if(start.isAfter(end))throw new br.com.tapeteskalke.exception.BusinessException("PERIODO_INVALIDO","A data inicial deve ser anterior ou igual à data final",org.springframework.http.HttpStatus.BAD_REQUEST);return ApiResponse.ok(service.financial(start,end));} }